    82	        values: Vec<Vec<ast::Expression>>,
    83	    ) -> Result<Plan> {
    84	        Ok(Plan::Insert { table, columns, values })
    85	    }
    86	
    87	    /// Builds an UPDATE plan.
    88	    fn build_update(
    89	        &self,
    90	        table: String,
    91	        set: BTreeMap<String, Option<ast::Expression>>,
    92	        r#where: Option<ast::Expression>,
    93	    ) -> Result<Plan> {
    94	        Ok(Plan::Update { table, set, r#where })
    95	    }
    96	
    97	    /// Builds a SELECT plan.
    98	    #[allow(clippy::too_many_arguments)]
    99	    fn build_select(
   100	        &self,
   101	        mut select: Vec<(ast::Expression, Option<String>)>,
   102	        from: Vec<ast::From>,
   103	        r#where: Option<ast::Expression>,
   104	        group_by: Vec<ast::Expression>,
   105	        having: Option<ast::Expression>,
   106	        order_by: Vec<(ast::Expression, ast::Direction)>,
   107	        offset: Option<ast::Expression>,
   108	        limit: Option<ast::Expression>,
   109	    ) -> Result<Plan> {
   110	        // If no FROM clause, check if we have constant expressions
   111	        if from.is_empty() {
   112	            // For constant selects, we need a VALUES node
   113	            // Check if all expressions are constant (no column references)
   114	            let mut has_columns = false;
   115	            for (expr, _) in &select {
   116	                if expr.contains(&|e| matches!(e, ast::Expression::Column(_, _))) {
   117	                    has_columns = true;
   118	                    break;
   119	                }
   120	            }
   121	            
   122	            if !has_columns {
   123	                // Constant select - create a VALUES node with a blank row
   124	                let mut scope = Scope::new();
   125	                let mut expressions = Vec::new();
   126	                for (expr, alias) in &select {
   127	                    let built_expr = self.build_expression(expr.clone(), &scope)?;
   128	                    expressions.push((built_expr, alias.clone()));
   129	                }
   130	                return Ok(Plan::Select {
   131	                    select: expressions,
   132	                    from: vec![],
   133	                    r#where: None,
   134	                    group_by: vec![],
   135	                    having: None,
   136	                    order_by: vec![],
   137	                    offset: None,
   138	                    limit: None,
   139	                });
   140	            }
   141	        }
   142	
   143	        // Build FROM clause
   144	        let mut scope = Scope::new();
   145	        let from_node = if from.is_empty() {
   146	            // No FROM clause with columns - error
   147	            return errinput!("SELECT requires a FROM clause when selecting columns");
   148	        } else {
   149	            self.build_from_clause(from, &mut scope)?
   150	        };
   151	
   152	        // Build WHERE clause
   153	        let where_expr = if let Some(expr) = r#where {
   154	            Some(self.build_expression(expr, &scope)?)
   155	        } else {
   156	            None
   157	        };
   158	
   159	        // Collect aggregates before building GROUP BY
   160	        let aggregates = self.collect_aggregates(&select, &having, &order_by);
   161	
   162	        // Build GROUP BY and aggregate
   163	        let mut node = from_node;
   164	        let mut aggregate_scope = scope.spawn();
   165	        
   166	        if !group_by.is_empty() || !aggregates.is_empty() {
   167	            // Build GROUP BY expressions
   168	            let mut group_by_exprs = Vec::new();
   169	            for expr in &group_by {
   170	                group_by_exprs.push(self.build_expression(expr.clone(), &scope)?);
   171	            }
   172	            
   173	            // Build aggregate expressions
   174	            let mut agg_exprs = Vec::new();
   175	            for expr in &aggregates {
   176	                agg_exprs.push(self.build_expression(expr.clone(), &scope)?);
   177	            }
   178	            
   179	            node = self.build_aggregate(node, group_by_exprs, agg_exprs, &mut aggregate_scope)?;
   180	        }
   181	
   182	        // Build SELECT expressions
   183	        let mut select_exprs = Vec::new();
   184	        for (expr, alias) in &select {
   185	            select_exprs.push((self.build_expression(expr.clone(), &aggregate_scope)?, alias.clone()));
   186	        }
   187	
   188	        // Build HAVING clause
   189	        let having_expr = if let Some(expr) = having {
   190	            Some(self.build_expression(expr, &aggregate_scope)?)
   191	        } else {
   192	            None
   193	        };
   194	
   195	        // Build ORDER BY expressions
   196	        let mut order_by_exprs = Vec::new();
   197	        for (expr, dir) in &order_by {
   198	            order_by_exprs.push((self.build_expression(expr.clone(), &aggregate_scope)?, dir.clone()));
   199	        }
   200	
   201	        // Build OFFSET and LIMIT
   202	        let offset_expr = if let Some(expr) = offset {
   203	            Some(self.build_expression(expr, &aggregate_scope)?)
   204	        } else {
   205	            None
   206	        };
   207	
   208	        let limit_expr = if let Some(expr) = limit {
   209	            Some(self.build_expression(expr, &aggregate_scope)?)
   210	        } else {
   211	            None
   212	        };
   213	
   214	        Ok(Plan::Select {
   215	            select: select_exprs,
   216	            from: vec![Node::Select {
   217	                source: Box::new(node),
   218	                select: select_exprs.clone(),
   219	                r#where: where_expr.clone(),
   220	                group_by: vec![],
   221	                having: None,
   222	                order_by: vec![],
   223	                offset: None,
   224	                limit: None,
   225	            }],
   226	            r#where: where_expr,
   227	            group_by: vec![],
   228	            having: having_expr,
   229	            order_by: order_by_exprs,
   230	            offset: offset_expr,
   231	            limit: limit_expr,
   232	        })
   233	    }
   234	
   235	    /// Builds a FROM clause consisting of one or more items.
   236	    fn build_from_clause(&self, from: Vec<ast::From>, scope: &mut Scope) -> Result<Node> {
   237	        let mut node = self.build_from(from[0].clone(), scope)?;
   238	        
   239	        for from_item in from.into_iter().skip(1) {
   240	            let join_node = self.build_from(from_item, scope)?;
   241	            // For now, just chain them - the optimizer will handle joins
   242	            node = Node::Join {
   243	                left: Box::new(node),
   244	                right: Box::new(join_node),
   245	                r#type: ast::JoinType::Inner,
   246	                predicate: None,
   247	            };
   248	        }
   249	        
   250	        Ok(node)
   251	    }
   252	
   253	    /// Builds FROM items, which can either be a single table or a chained join
   254	    /// of multiple tables.
   255	    fn build_from(&self, from: ast::From, parent_scope: &mut Scope) -> Result<Node> {
   256	        match from {
   257	            ast::From::Table { name, alias } => {
   258	                let table = self.catalog.must_get_table(&name)?;
   259	                let table_name = alias.unwrap_or_else(|| name.clone());
   260	                
   261	                let mut scope = Scope::from_table(&table)?;
   262	                scope.add_table(&table, Some(&table_name))?;
   263	                
   264	                // Merge with parent scope
   265	                parent_scope.merge(scope)?;
   266	                
   267	                Ok(Node::Scan {
   268	                    table: name,
   269	                    alias: alias,
   270	                    filter: None,
   271	                })
   272	            }
   273	            ast::From::Join { left, right, r#type, predicate } => {
   274	                let left_node = self.build_from(*left, parent_scope)?;
   275	                let right_node = self.build_from(*right, parent_scope)?;
   276	                
   277	                Ok(Node::Join {
   278	                    left: Box::new(left_node),
   279	                    right: Box::new(right_node),
   280	                    r#type,
   281	                    predicate: predicate.map(|e| self.build_expression(e, parent_scope)).transpose()?,
   282	                })
   283	            }
   284	        }
   285	    }
   286	
   287	    /// Builds an aggregate node.
   288	    fn build_aggregate(
   289	        &self,
   290	        source: Node,
   291	        mut group_by: Vec<ast::Expression>,
   292	        mut aggregates: Vec<ast::Expression>,
   293	        scope: &mut Scope,
   294	    ) -> Result<Node> {
   295	        // Build aggregate functions
   296	        let mut agg_functions = Vec::new();
   297	        for expr in &aggregates {
   298	            agg_functions.push(self.build_aggregate_function(expr.clone(), scope)?);
   299	        }
   300	        
   301	        Ok(Node::Aggregate {
   302	            source: Box::new(source),
   303	            group_by,
   304	            aggregates: agg_functions,
   305	        })
   306	    }
   307	
   308	    /// Builds an aggregate function from an AST expression.
   309	    fn build_aggregate_function(expr: ast::Expression, scope: &Scope) -> Result<Aggregate> {
   310	        let ast::Expression::Function(name, args) = expr else {
   311	            return errinput!("expected aggregate function");
   312	        };
   313	        
   314	        let args = args.into_iter()
   315	            .map(|arg| {
   316	                // For aggregate arguments, we need to evaluate them in the parent scope
   317	                // For now, just return a simple expression
   318	                Ok(Expression::Column(None, String::new()))
   319	            })
   320	            .collect::<Result<Vec<_>>>()?;
   321	        
   322	        Ok(Aggregate {
   323	            name,
   324	            args,
   325	        })
   326	    }
   327	
   328	    /// Checks whether a given AST expression is an aggregate function.
   329	    fn is_aggregate_function(expr: &ast::Expression) -> bool {
   330	        matches!(expr, ast::Expression::Function(name, _) if matches!(name.as_str(), 
   331	            "count" | "sum" | "avg" | "min" | "max" | "median" | "string_agg"
   332	        ))
   333	    }
   334	
   335	    /// Collects aggregate functions from SELECT, HAVING, and ORDER BY clauses.
   336	    fn collect_aggregates(
   337	        select: &[(ast::Expression, Option<String>)],
   338	        having: &Option<ast::Expression>,
   339	        order_by: &[(ast::Expression, ast::Direction)],
   340	    ) -> Vec<ast::Expression> {
   341	        let mut aggregates = Vec::new();
   342	        
   343	        for (expr, _) in select {
   344	            expr.collect(&|e| Self::is_aggregate_function(e), &mut aggregates);
   345	        }
   346	        
   347	        if let Some(expr) = having {
   348	            expr.collect(&|e| Self::is_aggregate_function(e), &mut aggregates);
   349	        }
   350	        
   351	        for (expr, _) in order_by {
   352	            expr.collect(&|e| Self::is_aggregate_function(e), &mut aggregates);
   353	        }
   354	        
   355	        aggregates
   356	    }
